//! Generated files: a source file whose top-level `@memo` begins
//! `Generated from` or `Generated by` (SPEC §4.10) says another program
//! writes it, and how to run that program again. An edit to the file is lost
//! the next time it runs, so a problem in it is fixed where the file is
//! generated from.
//!
//! [`mark`] gives each diagnostic in a generated file a related place at the
//! memo, whose note is the memo's text, and drops the fixes that would edit a
//! generated file. Every tool calls it on what it reports: `ascribe check`
//! (through [`diagnose`](crate::diagnose)), the language server, and the
//! conformance adapters.

use std::collections::HashMap;

use ascribe_core::{FileId, Location, Span};
use ascribe_syntax::{Block, BlockKind, ParseOptions, PrimaryValue, parse, raw_container_text};

use crate::{Diagnostic, Project, RelatedInfo};

/// What a memo that says its file is generated begins with.
const SAYS: [&str; 2] = ["Generated from ", "Generated by "];

/// What the note a diagnostic in a generated file carries begins with.
pub const NOTE: &str = "This file is generated, and an edit to it is lost: ";

/// The memo that says a file is generated.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Generated {
    /// The memo's opening line.
    pub span: Span,
    /// Its text, whitespace runs one space: what generates the file, and how
    /// to run it again.
    pub text: String,
}

impl Generated {
    /// The note a diagnostic in the file carries at the memo.
    pub fn note(&self) -> String {
        format!("{NOTE}{}", self.text)
    }
}

/// The memo among `blocks`, the top-level blocks of a file whose text is
/// `source`, that says the file is generated: the first whose text begins
/// with `Generated from` or `Generated by`.
pub fn generated_memo(source: &str, blocks: &[Block]) -> Option<Generated> {
    blocks.iter().find_map(|block| {
        let (span, text) = match &block.kind {
            BlockKind::Directive(line) if line.name == "memo" => match &line.primary {
                Some(PrimaryValue::Line(primary)) => (line.span, primary.text.clone()),
                _ => return None,
            },
            BlockKind::Container(c) if c.opener.name == "memo" => {
                (c.opener.span, raw_container_text(source, c)?)
            }
            _ => return None,
        };
        let text = text.split_whitespace().collect::<Vec<_>>().join(" ");
        SAYS.iter()
            .any(|says| text.starts_with(says))
            .then_some(Generated { span, text })
    })
}

/// The memo of the source file `file` that says it's generated, when it has
/// one.
pub fn of_file(project: &Project, file: FileId) -> Option<Generated> {
    let source = project.sources().iter().find(|s| s.id == file)?;
    // Most files say nothing of the kind, and needn't be parsed to know.
    if !source.text.contains("Generated") {
        return None;
    }
    let model = project.model();
    let options = ParseOptions::new(model.directive_schemas())
        .with_file(file)
        .with_note_types(model.notes.iter().map(|n| n.name.clone()).collect());
    generated_memo(&source.text, &parse(&source.text, &options).blocks)
}

/// `diagnostics`, with each one in a generated file related to the memo that
/// says so, and without the fixes that edit a generated file.
pub fn mark(project: &Project, mut diagnostics: Vec<Diagnostic>) -> Vec<Diagnostic> {
    let mut known: HashMap<FileId, Option<Generated>> = HashMap::new();
    let mut generated = |file: FileId| -> Option<Generated> {
        known
            .entry(file)
            .or_insert_with(|| of_file(project, file))
            .clone()
    };
    for d in &mut diagnostics {
        d.fixes.retain(|fix| generated(fix.file).is_none());
        let file = d.location.file;
        if let Some(memo) = generated(file) {
            let related = RelatedInfo {
                location: Location::new(file, memo.span),
                message: memo.note(),
            };
            if !d.related.contains(&related) {
                d.related.push(related);
            }
        }
    }
    diagnostics
}
